const sing = (w: string) => (w.length > 4 && /(ches|shes|sses|xes)$/.test(w) ? w.slice(0, -2) : w.length > 3 && w.endsWith('s') && !w.endsWith('ss') ? w.slice(0, -1) : w);
let entries: { e: string; lw: string[]; tags: string[] }[] | null = null;
const all = () => (entries ??= INDEX.split('\n').map((l) => {
  const [e, label, tags] = l.split('|');
  return { e, lw: label.split(/[\s:-]+/).map(sing), tags: (tags || '').split(' ').filter(Boolean).map(sing) };
}));
const STOP = new Set(['a', 'an', 'the', 'my', 'your', 'some', 'into', 'in', 'to', 'like', 'please', 'pls', 'now', 'for', 'me', 'of', 'cute', 'little', 'tiny', 'yourself', 'shape', 'form', 'as', 'with', 'and', 'one', 'real', 'really']);

/** The emoji that best shows a thing ("giraffe", "red heart", "big fluffy dog"), or null. */
export function findEmoji(phrase: string): string | null {
  const words = phrase.toLowerCase().replace(/[^a-z0-9\s'-]/g, ' ').split(/\s+/).filter((w) => w && !STOP.has(w)).map(sing);
  if (!words.length) return null;
  const best = (ws: string[]) => {
    let pick: string | null = null, top = 0;
    for (const it of all()) {
      let sc = 0;
      if (it.lw.join(' ') === ws.join(' ')) sc = 100;
      else if (ws.every((w) => it.lw.includes(w))) sc = 70 - (it.lw.length - ws.length) * 4;
      else if (ws.length === 1 && it.tags.includes(ws[0])) sc = 45 - it.lw.length;
      else if (ws.every((w) => it.lw.includes(w) || it.tags.includes(w))) sc = 40 - it.lw.length;
      if (sc > top) { top = sc; pick = it.e; }
    }
    return top >= 30 ? pick : null;
  };
  // Otherwise the thing itself is usually the last word ("a big fluffy dog")
  return best(words) || (words.length > 1 ? best([words[words.length - 1]]) : null);
}

const WATER = /\b(go back|turn back|change back|back to (water|normal|yourself|you)|be (water|yourself|normal)|normal again|just water|yourself again)\b/i;
const ASK = [
  /\b(?:turn|morph|change|transform|shape-?shift|shift)\s+(?:yourself\s+|urself\s+|you\s+)?(?:in ?to|to)\s+(.+)/i,
  /\b(?:become|look like|be like|make yourself(?: into)?|take the shape of|be)\s+(?:a|an|the|my|some)\s+(.+)/i,
  /\b(?:become|look like)\s+(.+)/i,
];

export type ShapeAsk = { water: true } | { subject: string; text?: string };

/** Whether a message asks Belluh to take a shape, and what. */
export function shapeRequest(text: string): ShapeAsk | null {
  if (WATER.test(text)) return { water: true };
  for (const r of ASK) {
    const m = r.exec(text);
    if (!m) continue;
    const subject = m[1].split(/[.!?;]| and | so | for me| please| now\b/i)[0].replace(/^["'“]|["'”]$/g, '').trim().replace(/^(?:a|an|the|my|some)\s+/i, '').slice(0, 40);
    if (!subject) continue;
    const letter = /^(?:the\s+)?(?:letter|number)\s+["'“]?([a-z0-9])["'”]?$/i.exec(subject);
    if (letter) return { subject, text: letter[1].toUpperCase() };
    return { subject };
  }
  return null;
}

/** The shape to take right away for a request, or null when Belluh should decide. */
export function instantShape(ask: ShapeAsk): ShapeSpec | 'water' | null {
  if ('water' in ask) return 'water';
  if (ask.text) return { text: ask.text };
  // A heart of any kind ("heart", "a love heart", "heart shape") is one clean heart, not an emoji with extras
  if (/\b(?:heart|hearts|love)\b/i.test(ask.subject) && !/\b(?:broken|anatomical|organ|eyes?|hands?|cat|face|on fire|mending)\b/i.test(ask.subject)) return { path: HEART_PATH };
  const emoji = findEmoji(ask.subject);
  return emoji ? { emoji } : null;
}
